        token.renounceOwnership();
        console.log("Trigger Operation: Ownership renounced");

        // Verify ownership is renounced
        assertEq(token.owner(), address(0), "Ownership should be renounced");

        console.log("--- AFTER-Trigger UpdateRouter ---");
