        console.log("Router address after renounce:", routerAfterRenounce);
        require(routerAfterRenounce == newRouter1, "Router address unchanged");

        // Attempt to update router (should revert)
        address newRouter2 = address(0x2222);
        vm.prank(owner);
        console.log("Trigger Operation: Attempt update router to", newRouter2);
        vm.expectRevert("Ownable: caller is not the owner");
        token.updateRouter(newRouter2);

        // Final state verification
